// Provedor Simulado para Testes Locais e CI
const request = $input.item.json.request || $input.item.json;
const suggestions = (request.groups || []).map((group) => {
  const anchorId = group.anchorId;
  const candidates = (group.entries || []).filter(e => e.id !== anchorId);
  const candidateIds = candidates.length > 0 ? [candidates[0].id] : [];
  return {
    groupId: group.groupId,
    anchorId: anchorId,
    candidateIds: candidateIds,
    decision: candidateIds.length > 0 ? 'SUGGEST_MATCH' : 'NO_MATCH',
    confidenceBps: 8500,
    reasonCode: 'HISTORY_SIMILARITY',
    explanationPtBr: 'Correspondência provável identificada por similaridade no provedor simulado.'
  };
});

return {
  json: {
    contractVersion: '1.0',
    requestId: request.requestId,
    provider: 'simulated',
    model: 'simulated-v1',
    promptVersion: request.promptVersion || 'match-advisor-v1',
    suggestions: suggestions
  }
};
